fn drawingml_image_fill_mode(fill: &a::BlipFill) -> InlineShapeImageFillMode {
  match fill.blip_fill_choice.as_ref() {
    Some(a::BlipFillChoice::Stretch(_)) => InlineShapeImageFillMode::Stretch,
    Some(a::BlipFillChoice::Tile(tile)) => InlineShapeImageFillMode::DrawingMlTile(tile.clone()),
    // Office treats an omitted bitmap mode on a shape fill as tiled.
    None => InlineShapeImageFillMode::DrawingMlTile(Box::default()),
  }
}

fn resolve_drawingml_solid_fill(
  fill: &a::SolidFill,
  theme_colors: &ThemeColors,
) -> Option<ResolvedColor> {
  resolved_docx_drawing_color(
    Color::from_solid_fill_choice(fill.solid_fill_choice.as_ref()?)?,
    theme_colors,
  )
}

fn drawingml_pattern_fill(
  fill: &a::PatternFill,
  theme_colors: &ThemeColors,
) -> Option<common::PatternFill> {
  let foreground = match fill
    .foreground_color
    .as_ref()
    .and_then(|color| color.foreground_color_choice.as_ref())
  {
    Some(choice) => resolve_drawingml_foreground_color(choice, theme_colors)?,
    None => ResolvedColor {
      color: RgbColor { r: 0, g: 0, b: 0 },
      opacity: 1.0,
    },
  };
  let background = match fill
    .background_color
    .as_ref()
    .and_then(|color| color.background_color_choice.as_ref())
  {
    Some(choice) => resolve_drawingml_background_color(choice, theme_colors)?,
    None => ResolvedColor {
      color: RgbColor {
        r: u8::MAX,
        g: u8::MAX,
        b: u8::MAX,
      },
      opacity: 1.0,
    },
  };
  Some(common::PatternFill::drawingml(
    common::drawingml_pattern::hatch_style(fill.preset),
    common_rgb(foreground.color, foreground.opacity),
    common_rgb(background.color, background.opacity),
  ))
}

fn drawingml_pattern_fill_with_placeholder(
  fill: &a::PatternFill,
  theme_colors: &ThemeColors,
  placeholder_color: Option<&Color>,
) -> Option<common::PatternFill> {
  let foreground = match fill
    .foreground_color
    .as_ref()
    .and_then(|color| color.foreground_color_choice.as_ref())
  {
    Some(choice) => docx_image_color_with_placeholder(
      Color::from_foreground_color_choice(choice)?,
      theme_colors,
      placeholder_color,
    )?,
    None => common::Color {
      r: 0,
      g: 0,
      b: 0,
      a: u8::MAX,
    },
  };
  let background = match fill
    .background_color
    .as_ref()
    .and_then(|color| color.background_color_choice.as_ref())
  {
    Some(choice) => docx_image_color_with_placeholder(
      Color::from_background_color_choice(choice)?,
      theme_colors,
      placeholder_color,
    )?,
    None => common::Color {
      r: u8::MAX,
      g: u8::MAX,
      b: u8::MAX,
      a: u8::MAX,
    },
  };
  Some(common::PatternFill::drawingml(
    common::drawingml_pattern::hatch_style(fill.preset),
    foreground,
    background,
  ))
}

fn drawingml_gradient_fill(
  fill: &a::GradientFill,
  theme_colors: &ThemeColors,
) -> Option<common::Fill<'static>> {
  drawingml_gradient_fill_with_placeholder(fill, theme_colors, None)
}

fn drawingml_gradient_fill_with_placeholder(
  fill: &a::GradientFill,
  theme_colors: &ThemeColors,
  placeholder_color: Option<&Color>,
) -> Option<common::Fill<'static>> {
  let mut stops = fill
    .gradient_stop_list
    .as_ref()?
    .gradient_stop
    .iter()
    .filter_map(|stop| {
      let authored = Color::from_gradient_stop_choice(stop.gradient_stop_choice.as_ref()?)?;
      let color = if let Some(placeholder_color) = placeholder_color {
        docx_image_color_with_placeholder(authored, theme_colors, Some(placeholder_color))?
      } else {
        let color = resolved_docx_drawing_color(authored, theme_colors)?;
        common_rgb(color.color, color.opacity)
      };
      Some(common::GradientStop {
        position: stop.position.as_ratio() as f32,
        color,
        scheme: None,
      })
    })
    .collect::<Vec<_>>();
  stops.sort_by(|left, right| left.position.total_cmp(&right.position));
  if stops.is_empty() {
    return None;
  }
  let interpolation = word_fixed_gradient_interpolation(&stops);
  let (angle_degrees, scaled, path) = match fill.gradient_fill_choice.as_ref()? {
    a::GradientFillChoice::LinearGradientFill(linear) => (
      Some(linear.angle.unwrap_or_default() as f32 / 60_000.0),
      linear.scaled.as_ref().is_some_and(|value| value.as_bool()),
      None,
    ),
    a::GradientFillChoice::PathGradientFill(path) => (
      None,
      false,
      Some(common::drawingml_gradient::resolve_path_gradient(
        fill,
        path,
        common::Transform::default(),
      )),
    ),
  };
  Some(common::Fill::Gradient(common::GradientFill {
    stops,
    angle_degrees,
    definition_bounds: None,
    line: None,
    interpolation,
    scaled,
    rotate_with_shape: Some(
      fill
        .rotate_with_shape
        .as_ref()
        .is_none_or(|value| value.as_bool()),
    ),
    path,
  }))
}

fn drawingml_shape_properties_common_fill(
  properties: &DrawingMlShapeProperties,
  theme_colors: &ThemeColors,
) -> Option<common::Fill<'static>> {
  match properties.fill()? {
    DrawingMlFillProperties::NoFill => Some(common::Fill::None),
    DrawingMlFillProperties::Solid(fill) => {
      let color = resolve_drawingml_solid_fill(fill, theme_colors)?;
      Some(common::Fill::Solid(common_rgb(color.color, color.opacity)))
    }
    DrawingMlFillProperties::Gradient(fill) => drawingml_gradient_fill(fill, theme_colors),
    DrawingMlFillProperties::Pattern(fill) => {
      drawingml_pattern_fill(fill, theme_colors).map(common::Fill::Pattern)
    }
  }
}

fn drawingml_blip_common_fill(fill: &a::BlipFill) -> common::Fill<'static> {
  let relationship_id = fill.blip.as_deref().and_then(|blip| {
    blip
      .embed
      .as_deref()
      .or(blip.link.as_deref())
      .map(|id| Cow::Owned(id.to_string()))
  });
  common::Fill::Image {
    relationship_id,
    tile: matches!(fill.blip_fill_choice, Some(a::BlipFillChoice::Tile(_))),
  }
}

fn drawingml_chart_shape_common_style(
  properties: Option<&c::ChartShapeProperties>,
  theme_colors: &ThemeColors,
) -> common::ShapeStyle<'static> {
  let Some(properties) = properties else {
    return common::ShapeStyle::default();
  };
  let fill = match properties.chart_shape_properties_choice2.as_ref() {
    None => common::ShapeStyleValue::Unspecified,
    Some(c::ChartShapePropertiesChoice2::NoFill(_)) => common::ShapeStyleValue::NoPaint,
    Some(c::ChartShapePropertiesChoice2::SolidFill(fill)) => resolve_drawingml_solid_fill(
      fill,
      theme_colors,
    )
    .map_or(common::ShapeStyleValue::Unspecified, |paint| {
      common::ShapeStyleValue::Paint(common::Fill::Solid(common_rgb(paint.color, paint.opacity)))
    }),
    Some(c::ChartShapePropertiesChoice2::GradientFill(fill)) => {
      drawingml_gradient_fill(fill, theme_colors).map_or(
        common::ShapeStyleValue::Unspecified,
        common::ShapeStyleValue::Paint,
      )
    }
    Some(c::ChartShapePropertiesChoice2::PatternFill(fill)) => {
      drawingml_pattern_fill(fill, theme_colors)
        .map_or(common::ShapeStyleValue::Unspecified, |fill| {
          common::ShapeStyleValue::Paint(common::Fill::Pattern(fill))
        })
    }
    Some(c::ChartShapePropertiesChoice2::BlipFill(fill)) => {
      common::ShapeStyleValue::Paint(drawingml_blip_common_fill(fill))
    }
  };
  let stroke = match properties.outline.as_deref() {
    None => common::ShapeStyleValue::Unspecified,
    Some(outline)
      if matches!(
        outline.outline_choice1.as_ref(),
        Some(a::OutlineChoice::NoFill(_))
      ) =>
    {
      common::ShapeStyleValue::NoPaint
    }
    Some(outline) => drawingml_outline_common_stroke(outline, theme_colors).map_or(
      common::ShapeStyleValue::Unspecified,
      common::ShapeStyleValue::Paint,
    ),
  };
  common::ShapeStyle { fill, stroke }
}

fn drawingml_chart_area_common_style(
  properties: Option<&c::ShapeProperties>,
  theme_colors: &ThemeColors,
) -> common::ShapeStyle<'static> {
  let Some(properties) = properties else {
    return common::ShapeStyle::default();
  };
  let fill = match properties.shape_properties_choice2.as_ref() {
    None | Some(c::ShapePropertiesChoice2::GroupFill) => common::ShapeStyleValue::Unspecified,
    Some(c::ShapePropertiesChoice2::NoFill(_)) => common::ShapeStyleValue::NoPaint,
    Some(c::ShapePropertiesChoice2::SolidFill(fill)) => resolve_drawingml_solid_fill(
      fill,
      theme_colors,
    )
    .map_or(common::ShapeStyleValue::Unspecified, |paint| {
      common::ShapeStyleValue::Paint(common::Fill::Solid(common_rgb(paint.color, paint.opacity)))
    }),
    Some(c::ShapePropertiesChoice2::GradientFill(fill)) => {
      drawingml_gradient_fill(fill, theme_colors).map_or(
        common::ShapeStyleValue::Unspecified,
        common::ShapeStyleValue::Paint,
      )
    }
    Some(c::ShapePropertiesChoice2::PatternFill(fill)) => {
      drawingml_pattern_fill(fill, theme_colors)
        .map_or(common::ShapeStyleValue::Unspecified, |fill| {
          common::ShapeStyleValue::Paint(common::Fill::Pattern(fill))
        })
    }
    Some(c::ShapePropertiesChoice2::BlipFill(fill)) => {
      common::ShapeStyleValue::Paint(drawingml_blip_common_fill(fill))
    }
  };
  let stroke = match properties.outline.as_deref() {
    None => common::ShapeStyleValue::Unspecified,
    Some(outline)
      if matches!(
        outline.outline_choice1.as_ref(),
        Some(a::OutlineChoice::NoFill(_))
      ) =>
    {
      common::ShapeStyleValue::NoPaint
    }
    Some(outline) => drawingml_outline_common_stroke(outline, theme_colors).map_or(
      common::ShapeStyleValue::Unspecified,
      common::ShapeStyleValue::Paint,
    ),
  };
  common::ShapeStyle { fill, stroke }
}

