fn thai_cardinal_number(value: i32) -> String {
  const DIGITS: [&str; 10] = [
    "ศูนย์",
    "หนึ่ง",
    "สอง",
    "สาม",
    "สี่",
    "ห้า",
    "หก",
    "เจ็ด",
    "แปด",
    "เก้า",
  ];
  if value < 0 {
    return format!("ลบ{}", thai_cardinal_number(value.saturating_abs()));
  }
  if value < 10 {
    return DIGITS[value as usize].to_string();
  }
  if value < 100 {
    let tens = value / 10;
    let ones = value % 10;
    let mut output = match tens {
      1 => "สิบ".to_string(),
      2 => "ยี่สิบ".to_string(),
      _ => format!("{}สิบ", DIGITS[tens as usize]),
    };
    if ones == 1 {
      output.push_str("เอ็ด");
    } else if ones > 1 {
      output.push_str(DIGITS[ones as usize]);
    }
    return output;
  }
  for (scale, name) in [
    (1_000_000, "ล้าน"),
    (100_000, "แสน"),
    (10_000, "หมื่น"),
    (1_000, "พัน"),
    (100, "ร้อย"),
  ] {
    if value >= scale {
      let quotient = value / scale;
      let remainder = value % scale;
      let mut output = format!("{}{name}", thai_cardinal_number(quotient));
      if remainder > 0 {
        output.push_str(&thai_cardinal_number(remainder));
      }
      return output;
    }
  }
  value.to_string()
}

fn vietnamese_cardinal_number(value: i32) -> String {
  const DIGITS: [&str; 10] = [
    "không", "một", "hai", "ba", "bốn", "năm", "sáu", "bảy", "tám", "chín",
  ];
  if value < 0 {
    return format!("âm {}", vietnamese_cardinal_number(value.saturating_abs()));
  }
  if value < 10 {
    return DIGITS[value as usize].to_string();
  }
  if value < 20 {
    let ones = value % 10;
    return if ones == 0 {
      "mười".to_string()
    } else {
      format!(
        "mười {}",
        if ones == 5 {
          "lăm"
        } else {
          DIGITS[ones as usize]
        }
      )
    };
  }
  if value < 100 {
    let tens = value / 10;
    let ones = value % 10;
    let mut output = format!("{} mươi", DIGITS[tens as usize]);
    if ones > 0 {
      output.push(' ');
      output.push_str(match ones {
        1 => "mốt",
        4 => "tư",
        5 => "lăm",
        _ => DIGITS[ones as usize],
      });
    }
    return output;
  }
  if value < 1_000 {
    let hundreds = value / 100;
    let remainder = value % 100;
    let mut output = format!("{} trăm", DIGITS[hundreds as usize]);
    if remainder > 0 {
      if remainder < 10 {
        output.push_str(" lẻ ");
        output.push_str(DIGITS[remainder as usize]);
      } else {
        output.push(' ');
        output.push_str(&vietnamese_cardinal_number(remainder));
      }
    }
    return output;
  }
  for (scale, name) in [
    (1_000_000_000, "tỷ"),
    (1_000_000, "triệu"),
    (1_000, "nghìn"),
  ] {
    if value >= scale {
      let quotient = value / scale;
      let remainder = value % scale;
      let mut output = format!("{} {name}", vietnamese_cardinal_number(quotient));
      if remainder > 0 {
        output.push(' ');
        if scale == 1_000 && remainder < 100 {
          output.push_str("không trăm ");
          if remainder < 10 {
            output.push_str("lẻ ");
          }
        } else if remainder < 10 {
          output.push_str("lẻ ");
        }
        output.push_str(&vietnamese_cardinal_number(remainder));
      }
      return output;
    }
  }
  value.to_string()
}

fn cjk_digit_number(value: i32, digits: &[char; 10]) -> String {
  value
    .to_string()
    .chars()
    .map(|character| {
      character
        .to_digit(10)
        .map_or(character, |digit| digits[digit as usize])
    })
    .collect()
}

fn cjk_counting_number(
  value: i32,
  digits: &[char; 10],
  small_units: &[char; 3],
  group_units: &[char; 2],
  omit_leading_one_ten: bool,
) -> String {
  if value <= 0 {
    return value.to_string();
  }

  let mut groups = Vec::new();
  let mut remainder = value as u32;
  while remainder > 0 {
    groups.push((remainder % 10_000) as u16);
    remainder /= 10_000;
  }

  let mut output = String::new();
  let mut pending_zero = false;
  for group_index in (0..groups.len()).rev() {
    let group = groups[group_index];
    if group == 0 {
      if !output.is_empty() {
        pending_zero = true;
      }
      continue;
    }
    if !output.is_empty() && (pending_zero || group < 1_000) {
      output.push(digits[0]);
    }
    output.push_str(&cjk_counting_group(
      group,
      digits,
      small_units,
      omit_leading_one_ten && output.is_empty(),
    ));
    if group_index > 0 {
      output.push(group_units[group_index - 1]);
    }
    pending_zero = false;
  }
  output
}

fn cjk_counting_group(
  value: u16,
  digits: &[char; 10],
  units: &[char; 3],
  omit_leading_one_ten: bool,
) -> String {
  debug_assert!((1..10_000).contains(&value));
  let mut output = String::new();
  let mut pending_zero = false;
  for (position, divisor) in [1_000_u16, 100, 10, 1].into_iter().enumerate() {
    let digit = usize::from(value / divisor % 10);
    if digit == 0 {
      if !output.is_empty() && value % divisor != 0 {
        pending_zero = true;
      }
      continue;
    }
    if pending_zero {
      output.push(digits[0]);
      pending_zero = false;
    }
    let is_leading_ten = divisor == 10 && digit == 1 && output.is_empty() && omit_leading_one_ten;
    if !is_leading_ten {
      output.push(digits[digit]);
    }
    if divisor > 1 {
      output.push(units[2 - position]);
    }
  }
  output
}

fn english_ordinal_number(value: i32) -> String {
  if value <= 0 {
    return value.to_string();
  }
  let suffix = match value % 100 {
    11..=13 => "th",
    _ => match value % 10 {
      1 => "st",
      2 => "nd",
      3 => "rd",
      _ => "th",
    },
  };
  format!("{value}{suffix}")
}

fn english_cardinal_number(value: i32) -> String {
  capitalize_ascii_initial(&english_cardinal_lower(value))
}

fn english_ordinal_text(value: i32) -> String {
  capitalize_ascii_initial(&english_ordinal_lower(value))
}

fn numbering_language_primary(language: Option<&str>) -> &str {
  language
    .unwrap_or("en")
    .split(['-', '_'])
    .next()
    .unwrap_or("en")
}

fn localized_cardinal_number(value: i32, language: Option<&str>) -> String {
  match numbering_language_primary(language) {
    "en" => english_cardinal_number(value),
    "hi" => hindi_cardinal_number(value),
    "th" => thai_cardinal_number(value),
    "vi" => vietnamese_cardinal_number(value),
    "zh" | "ja" => cjk_counting_number(
      value,
      &['〇', '一', '二', '三', '四', '五', '六', '七', '八', '九'],
      &['十', '百', '千'],
      &['万', '亿'],
      true,
    ),
    "ko" => cjk_counting_number(
      value,
      &['영', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구'],
      &['십', '백', '천'],
      &['만', '억'],
      true,
    ),
    // Do not leak English application resources into an authored language
    // for which this renderer has no spellout rules. A decimal fallback is
    // stable and keeps locale expansion additive.
    _ => value.to_string(),
  }
}

fn localized_ordinal_number(value: i32, language: Option<&str>) -> String {
  match numbering_language_primary(language) {
    "en" => english_ordinal_number(value),
    "zh" | "ja" => format!("第{value}"),
    "ko" => format!("제{value}"),
    "th" => format!("ที่{value}"),
    "vi" => format!("thứ {value}"),
    "hi" => format!("{value}वाँ"),
    _ => value.to_string(),
  }
}

fn localized_ordinal_text(value: i32, language: Option<&str>) -> String {
  match numbering_language_primary(language) {
    "en" => english_ordinal_text(value),
    "hi" => match value {
      0 => "शून्यवाँ".to_string(),
      1 => "पहला".to_string(),
      2 => "दूसरा".to_string(),
      3 => "तीसरा".to_string(),
      4 => "चौथा".to_string(),
      5 => "पाँचवाँ".to_string(),
      6 => "छठा".to_string(),
      _ => format!("{}वाँ", hindi_cardinal_number(value)),
    },
    "th" => format!("ที่{}", thai_cardinal_number(value)),
    "vi" => match value {
      1 => "thứ nhất".to_string(),
      2 => "thứ nhì".to_string(),
      4 => "thứ tư".to_string(),
      _ => format!("thứ {}", vietnamese_cardinal_number(value)),
    },
    "zh" | "ja" => format!("第{}", localized_cardinal_number(value, language)),
    "ko" => format!("제{}", localized_cardinal_number(value, language)),
    _ => value.to_string(),
  }
}

fn english_cardinal_lower(value: i32) -> String {
  if value == 0 {
    return "zero".to_string();
  }
  if value < 0 {
    return format!("minus {}", english_cardinal_lower(value.saturating_abs()));
  }
  let mut remainder = i64::from(value);
  let mut groups = Vec::new();
  for (scale, name) in [
    (1_000_000_000_i64, "billion"),
    (1_000_000_i64, "million"),
    (1_000_i64, "thousand"),
  ] {
    if remainder >= scale {
      groups.push(format!(
        "{} {name}",
        english_cardinal_below_thousand((remainder / scale) as i32)
      ));
      remainder %= scale;
    }
  }
  if remainder > 0 {
    groups.push(english_cardinal_below_thousand(remainder as i32));
  }
  groups.join(" ")
}

fn english_cardinal_below_thousand(value: i32) -> String {
  debug_assert!((1..1000).contains(&value));
  let mut parts = Vec::new();
  let hundreds = value / 100;
  let remainder = value % 100;
  if hundreds > 0 {
    parts.push(format!(
      "{} hundred",
      english_cardinal_below_hundred(hundreds)
    ));
  }
  if remainder > 0 {
    parts.push(english_cardinal_below_hundred(remainder));
  }
  parts.join(" ")
}

fn english_cardinal_below_hundred(value: i32) -> String {
  const SMALL: [&str; 20] = [
    "zero",
    "one",
    "two",
    "three",
    "four",
    "five",
    "six",
    "seven",
    "eight",
    "nine",
    "ten",
    "eleven",
    "twelve",
    "thirteen",
    "fourteen",
    "fifteen",
    "sixteen",
    "seventeen",
    "eighteen",
    "nineteen",
  ];
  const TENS: [&str; 10] = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety",
  ];
  if value < 20 {
    return SMALL[value as usize].to_string();
  }
  let tens = TENS[(value / 10) as usize];
  let ones = value % 10;
  if ones == 0 {
    tens.to_string()
  } else {
    format!("{tens}-{}", SMALL[ones as usize])
  }
}

fn english_ordinal_lower(value: i32) -> String {
  if value <= 0 {
    return value.to_string();
  }
  for (scale, name) in [
    (1_000_000_000, "billionth"),
    (1_000_000, "millionth"),
    (1_000, "thousandth"),
    (100, "hundredth"),
  ] {
    if value % scale == 0 {
      return format!("{} {name}", english_cardinal_lower(value / scale));
    }
    if value > scale {
      return format!(
        "{} {}",
        english_cardinal_lower(value - value % scale),
        english_ordinal_lower(value % scale)
      );
    }
  }
  const SMALL_ORDINALS: [&str; 20] = [
    "zeroth",
    "first",
    "second",
    "third",
    "fourth",
    "fifth",
    "sixth",
    "seventh",
    "eighth",
    "ninth",
    "tenth",
    "eleventh",
    "twelfth",
    "thirteenth",
    "fourteenth",
    "fifteenth",
    "sixteenth",
    "seventeenth",
    "eighteenth",
    "nineteenth",
  ];
  if value < 20 {
    return SMALL_ORDINALS[value as usize].to_string();
  }
  let tens = value / 10;
  let ones = value % 10;
  if ones == 0 {
    return match tens {
      2 => "twentieth",
      3 => "thirtieth",
      4 => "fortieth",
      5 => "fiftieth",
      6 => "sixtieth",
      7 => "seventieth",
      8 => "eightieth",
      9 => "ninetieth",
      _ => unreachable!("value is below one hundred"),
    }
    .to_string();
  }
  format!(
    "{}-{}",
    english_cardinal_below_hundred(tens * 10),
    SMALL_ORDINALS[ones as usize]
  )
}

fn capitalize_ascii_initial(value: &str) -> String {
  let mut output = value.to_string();
  if let Some(first) = output.get_mut(0..1) {
    first.make_ascii_uppercase();
  }
  output
}

fn enclosed_decimal_number(value: i32, first_codepoint: u32) -> String {
  if !(1..=20).contains(&value) {
    return value.to_string();
  }
  char::from_u32(first_codepoint + value as u32 - 1)
    .expect("ECMA-376 enclosed decimal ranges are valid Unicode")
    .to_string()
}

fn circled_decimal_number(value: i32) -> String {
  let codepoint = match value {
    1..=20 => 0x2460 + value as u32 - 1,
    21..=35 => 0x3251 + value as u32 - 21,
    36..=50 => 0x32B1 + value as u32 - 36,
    _ => return value.to_string(),
  };
  char::from_u32(codepoint)
    .expect("ECMA-376 circled decimal ranges are valid Unicode")
    .to_string()
}

fn full_width_decimal_number(value: i32) -> String {
  value
    .to_string()
    .chars()
    .map(|character| match character {
      '0'..='9' => char::from_u32(0xFF10 + character as u32 - '0' as u32)
        .expect("full-width decimal range is valid Unicode"),
      _ => character,
    })
    .collect()
}

fn alpha_number(mut value: i32, upper: bool) -> String {
  if value <= 0 {
    return value.to_string();
  }
  let mut chars = Vec::new();
  while value > 0 {
    value -= 1;
    let base = if upper { b'A' } else { b'a' };
    chars.push((base + (value % 26) as u8) as char);
    value /= 26;
  }
  chars.iter().rev().collect()
}

fn roman_number(mut value: i32) -> String {
  if !(1..=3999).contains(&value) {
    return value.to_string();
  }
  let mut output = String::new();
  for (arabic, roman) in [
    (1000, "M"),
    (900, "CM"),
    (500, "D"),
    (400, "CD"),
    (100, "C"),
    (90, "XC"),
    (50, "L"),
    (40, "XL"),
    (10, "X"),
    (9, "IX"),
    (5, "V"),
    (4, "IV"),
    (1, "I"),
  ] {
    while value >= arabic {
      output.push_str(roman);
      value -= arabic;
    }
  }
  output
}

