  #[test]
  fn synthesized_numbering_ignores_inherited_small_caps_but_honors_level_small_caps() {
    // Source: LibreOffice sw/source/core/text/txtfld.cxx explicitly removes
    // paragraph small-caps from Word numbering. A w:lvl/w:rPr property still
    // belongs to the synthesized numbering text itself.
    let labels = [
      (
        br#"<w:lvl xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="cardinalText"/><w:lvlText w:val="%1."/></w:lvl>"#
          .as_slice(),
        false,
      ),
      (
        br#"<w:lvl xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="cardinalText"/><w:lvlText w:val="%1."/><w:rPr><w:smallCaps/></w:rPr></w:lvl>"#
          .as_slice(),
        true,
      ),
    ]
    .into_iter()
    .map(|(xml, expected_small_caps)| {
      let level = w::Level::from_bytes(xml).expect("numbering level");
      let mut catalog = NumberingCatalog {
        abstract_nums: HashMap::from([(
          4,
          AbstractNumbering {
            levels: HashMap::from([(0, numbering_level_model(&level, ImportSettings::default()))]),
            ..Default::default()
          },
        )]),
        nums: HashMap::from([(
          5,
          NumberingInstance {
            abstract_num_id: 4,
            overrides: HashMap::new(),
          },
        )]),
        ..Default::default()
      };
      let label = catalog
        .next_label(
          NumberingReference {
            num_id: Some(5),
            level_index: Some(0),
          },
          &mut ParagraphFormat::default(),
          &StylesCatalog::default(),
          TextStyle {
            small_caps: true,
            ..Default::default()
          },
          None,
          NumberingFormatMergeContext::default(),
        )
        .expect("numbering label");
      (label.style.small_caps, expected_small_caps)
    })
    .collect::<Vec<_>>();

    assert_eq!(labels, [(false, false), (true, true)]);
  }

  fn paragraph_mark_character_style_numbering_model(level_xml: &[u8]) -> Paragraph {
    let paragraph = w::Paragraph::from_bytes(
      br#"<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:pPr><w:numPr><w:ilvl w:val="0"/><w:numId w:val="1"/></w:numPr><w:rPr><w:rStyle w:val="Emphasis"/></w:rPr></w:pPr><w:r><w:t>Body</w:t></w:r></w:p>"#,
    )
    .expect("numbered paragraph with paragraph-mark character style");
    let level = w::Level::from_bytes(level_xml).expect("numbering level");
    let styles = StylesCatalog {
      styles: HashMap::from([(
        "Emphasis".to_string(),
        StyleEntry {
          style_type: Some(w::StyleValues::Character),
          run_style: TextStyle {
            color: RgbColor {
              r: 0xff,
              g: 0,
              b: 0,
            },
            color_is_automatic: false,
            ..Default::default()
          },
          run_overrides: RunStyleOverrides {
            italic: Some(true),
            ..Default::default()
          },
          ..Default::default()
        },
      )]),
      ..Default::default()
    };
    let mut numbering = NumberingCatalog {
      abstract_nums: HashMap::from([(
        1,
        AbstractNumbering {
          levels: HashMap::from([(0, numbering_level_model(&level, ImportSettings::default()))]),
          ..Default::default()
        },
      )]),
      nums: HashMap::from([(
        1,
        NumberingInstance {
          abstract_num_id: 1,
          overrides: HashMap::new(),
        },
      )]),
      ..Default::default()
    };

    paragraph_model(
      &paragraph,
      &styles,
      &mut numbering,
      &ImageCatalog::default(),
      &HyperlinkCatalog::default(),
      &CustomXmlBindings::default(),
      &mut FormWidgetIdAllocator::default(),
    )
  }

  #[test]
  fn paragraph_mark_character_style_is_applied_once_to_numbering() {
    let model = paragraph_mark_character_style_numbering_model(
      br#"<w:lvl xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/></w:lvl>"#,
    );

    assert_eq!(model.list_label.as_deref(), Some("1.\t"));
    assert!(model.list_label_style.italic);
    assert_eq!(
      model.list_label_style.color,
      RgbColor {
        r: 0xff,
        g: 0,
        b: 0
      }
    );
    assert!(!model.runs[0].style.italic);
    assert_eq!(model.runs[0].style.color, RgbColor { r: 0, g: 0, b: 0 });
  }

  #[test]
  fn numbering_level_format_remains_authoritative_over_paragraph_mark_style() {
    let model = paragraph_mark_character_style_numbering_model(
      br#"<w:lvl xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/><w:rPr><w:i w:val="0"/><w:color w:val="0000ff"/></w:rPr></w:lvl>"#,
    );

    assert!(!model.list_label_style.italic);
    assert_eq!(
      model.list_label_style.color,
      RgbColor {
        r: 0,
        g: 0,
        b: 0xff
      }
    );
  }

  #[test]
  fn empty_numbering_text_tabs_to_the_level_left_indent() {
    let level = w::Level::from_bytes(
      br#"<w:lvl xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val=""/><w:pPr><w:ind w:left="1432" w:hanging="1432"/></w:pPr></w:lvl>"#,
    )
    .expect("empty numbering level");
    let mut numbering = NumberingCatalog {
      abstract_nums: HashMap::from([(
        1,
        AbstractNumbering {
          levels: HashMap::from([(0, numbering_level_model(&level, ImportSettings::default()))]),
          ..Default::default()
        },
      )]),
      nums: HashMap::from([(
        1,
        NumberingInstance {
          abstract_num_id: 1,
          overrides: HashMap::new(),
        },
      )]),
      ..Default::default()
    };
    let paragraph = w::Paragraph::from_bytes(
      br#"<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:pPr><w:numPr><w:numId w:val="1"/></w:numPr></w:pPr><w:r><w:t>Here should be tab before</w:t></w:r></w:p>"#,
    )
    .expect("numbered paragraph");
    let mut form_widget_ids = FormWidgetIdAllocator::default();

    let model = paragraph_model(
      &paragraph,
      &StylesCatalog::default(),
      &mut numbering,
      &ImageCatalog::default(),
      &HyperlinkCatalog::default(),
      &CustomXmlBindings::default(),
      &mut form_widget_ids,
    );

    assert_eq!(model.list_label.as_deref(), Some("\t"));
    assert!((model.format.indent_left_pt - 71.6).abs() < 0.001);
    assert!((model.list_label_tab_stop_pt.unwrap_or_default() - 71.6).abs() < 0.001);
  }

  #[test]
  fn empty_numbering_text_with_no_suffix_keeps_the_hanging_first_line_origin() {
    let level = w::Level::from_bytes(
      br#"<w:lvl xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:ilvl="2"><w:start w:val="1"/><w:numFmt w:val="none"/><w:suff w:val="nothing"/><w:lvlText w:val=""/><w:pPr><w:tabs><w:tab w:val="num" w:pos="2409"/></w:tabs><w:ind w:left="2409" w:hanging="708"/></w:pPr></w:lvl>"#,
    )
    .expect("numbering level without a visible portion");
    let mut numbering = NumberingCatalog {
      abstract_nums: HashMap::from([(
        1,
        AbstractNumbering {
          levels: HashMap::from([(2, numbering_level_model(&level, ImportSettings::default()))]),
          ..Default::default()
        },
      )]),
      nums: HashMap::from([(
        1,
        NumberingInstance {
          abstract_num_id: 1,
          overrides: HashMap::new(),
        },
      )]),
      ..Default::default()
    };
    let paragraph = w::Paragraph::from_bytes(
      br#"<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:pPr><w:numPr><w:ilvl w:val="2"/><w:numId w:val="1"/></w:numPr></w:pPr><w:r><w:t>Note</w:t></w:r><w:r><w:tab/></w:r><w:r><w:t>Body</w:t></w:r></w:p>"#,
    )
    .expect("numbered paragraph");
    let mut form_widget_ids = FormWidgetIdAllocator::default();

    let model = paragraph_model(
      &paragraph,
      &StylesCatalog::default(),
      &mut numbering,
      &ImageCatalog::default(),
      &HyperlinkCatalog::default(),
      &CustomXmlBindings::default(),
      &mut form_widget_ids,
    );

    assert!(model.list_label.is_none());
    assert!((model.format.indent_left_pt - 120.45).abs() < 0.001);
    assert!((model.format.first_line_indent_pt + 35.4).abs() < 0.001);
    assert_eq!(model.format.tab_stops.len(), 1);
    assert_eq!(model.format.tab_stops[0].alignment, TabStopAlignment::Left);
    assert!((model.format.tab_stops[0].position_pt - 120.45).abs() < 0.001);
  }

  #[test]
  fn numbering_level_bound_to_paragraph_style_owns_the_style_indent() {
    let level = w::Level::from_bytes(
      br#"<w:lvl xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:pStyle w:val="Style1"/><w:lvlText w:val="%1."/><w:pPr><w:ind w:left="360" w:hanging="360"/></w:pPr></w:lvl>"#,
    )
    .expect("style-bound numbering level");
    let mut catalog = NumberingCatalog {
      abstract_nums: HashMap::from([(
        4,
        AbstractNumbering {
          levels: HashMap::from([(0, numbering_level_model(&level, ImportSettings::default()))]),
          ..Default::default()
        },
      )]),
      nums: HashMap::from([(
        5,
        NumberingInstance {
          abstract_num_id: 4,
          overrides: HashMap::new(),
        },
      )]),
      ..Default::default()
    };
    let mut format = ParagraphFormat {
      style_id: Some(Arc::from("Style1")),
      indent_left_pt: 36.0,
      indent_left_set: true,
      ..Default::default()
    };

    catalog
      .next_label(
        NumberingReference {
          num_id: Some(5),
          level_index: Some(0),
        },
        &mut format,
        &StylesCatalog::default(),
        TextStyle::default(),
        None,
        NumberingFormatMergeContext {
          style_numbering: true,
          ..Default::default()
        },
      )
      .expect("numbering label");

    assert_eq!(format.indent_left_pt, 18.0);
    assert_eq!(format.first_line_indent_pt, -18.0);

    let mut locally_indented_format = ParagraphFormat {
      style_id: Some(Arc::from("Style1")),
      indent_left_pt: 0.0,
      indent_left_set: true,
      first_line_indent_pt: 0.0,
      first_line_indent_set: true,
      ..Default::default()
    };
    catalog
      .next_label(
        NumberingReference {
          num_id: Some(5),
          level_index: Some(0),
        },
        &mut locally_indented_format,
        &StylesCatalog::default(),
        TextStyle::default(),
        None,
        NumberingFormatMergeContext {
          style_numbering: true,
          matched_style_indent_left: true,
          matched_style_first_line_indent: true,
          ..Default::default()
        },
      )
      .expect("numbering label");

    assert_eq!(locally_indented_format.indent_left_pt, 0.0);
    assert_eq!(locally_indented_format.first_line_indent_pt, 0.0);
  }

