  #[test]
  fn drawing_textboxes_extract_cached_text() {
    let xml = r#"<wps:wsp xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape" xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <wps:txbx>
    <w:txbxContent>
      <w:p><w:r><w:t>Modern text box</w:t></w:r></w:p>
      <w:p><w:r><w:t>Second line</w:t></w:r></w:p>
    </w:txbxContent>
  </wps:txbx>
</wps:wsp>"#;

    let shape = wps::WordprocessingShape::from_bytes(xml.as_bytes()).expect("typed WPS shape");
    let content = wordprocessing_shape_textbox_content(&shape).expect("typed textbox content");
    let blocks = textbox_blocks(
      content,
      &StylesCatalog::default(),
      &ImageCatalog::default(),
      &HyperlinkCatalog::default(),
    );
    let text: Vec<_> = blocks
      .iter()
      .filter_map(|block| match block {
        Block::Paragraph(paragraph) => Some(inline_text(&paragraph.inlines)),
        _ => None,
      })
      .collect();

    assert_eq!(text, ["Modern text box", "Second line"]);
  }

  #[test]
  fn drawing_textboxes_import_block_content_controls() {
    let xml = r#"<wps:wsp xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape" xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <wps:txbx>
    <w:txbxContent>
      <w:sdt>
        <w:sdtPr><w:date/></w:sdtPr>
        <w:sdtContent>
          <w:p><w:r><w:t>Click here to enter a date.</w:t></w:r></w:p>
        </w:sdtContent>
      </w:sdt>
    </w:txbxContent>
  </wps:txbx>
</wps:wsp>"#;

    let shape = wps::WordprocessingShape::from_bytes(xml.as_bytes()).expect("typed WPS shape");
    let content = wordprocessing_shape_textbox_content(&shape).expect("typed textbox content");
    let blocks = textbox_blocks_with_base(
      content,
      TextStyle {
        font_size_pt: 17.0,
        ..Default::default()
      },
      &StylesCatalog::default(),
      &ImageCatalog::default(),
      &HyperlinkCatalog::default(),
    );
    let Block::Paragraph(paragraph) = &blocks[0] else {
      panic!("content-control paragraph");
    };

    assert_eq!(
      inline_text(&paragraph.inlines),
      "Click here to enter a date."
    );
    let InlineItem::Text(run) = &paragraph.inlines[0] else {
      panic!("content-control text run");
    };
    assert_eq!(run.style.font_size_pt, 17.0);
  }

  #[test]
  fn style_chain_preserves_explicit_false_run_properties() {
    let mut catalog = StylesCatalog::default();
    catalog.styles.insert(
      "Base".into(),
      StyleEntry {
        style_type: Some(w::StyleValues::Paragraph),
        run_style: TextStyle {
          bold: true,
          italic: true,
          underline: true,
          ..Default::default()
        },
        ..Default::default()
      },
    );
    catalog.styles.insert(
      "Derived".into(),
      StyleEntry {
        style_type: Some(w::StyleValues::Paragraph),
        based_on: Some("Base".into()),
        run_overrides: RunStyleOverrides {
          bold: Some(false),
          underline: Some(false),
          ..Default::default()
        },
        ..Default::default()
      },
    );

    let style = catalog.run_style_with_base(
      Some("Derived"),
      TextStyle::default(),
      RunStyleOverrides::default(),
    );

    assert!(!style.bold);
    assert!(style.italic);
    assert!(!style.underline);
  }

  #[test]
  fn character_style_toggle_properties_reverse_inherited_values() {
    let mut catalog = StylesCatalog::default();
    catalog.styles.insert(
      "CapsEffects".into(),
      StyleEntry {
        style_type: Some(w::StyleValues::Character),
        run_overrides: RunStyleOverrides {
          bold: Some(true),
          complex_bold: Some(true),
          italic: Some(true),
          complex_italic: Some(true),
          strikethrough: Some(true),
          uppercase: Some(true),
          hidden: Some(true),
          legacy_outline: Some(true),
          legacy_shadow: Some(true),
          legacy_emboss: Some(true),
          ..Default::default()
        },
        ..Default::default()
      },
    );
    catalog.styles.insert(
      "SmallCapsImprint".into(),
      StyleEntry {
        style_type: Some(w::StyleValues::Character),
        run_overrides: RunStyleOverrides {
          small_caps: Some(true),
          legacy_imprint: Some(true),
          ..Default::default()
        },
        ..Default::default()
      },
    );

    let caps = catalog.character_run_style(
      Some("CapsEffects"),
      TextStyle {
        bold: true,
        complex_bold: Some(true),
        italic: true,
        complex_italic: Some(true),
        strikethrough: true,
        uppercase: true,
        hidden: true,
        legacy_outline: true,
        legacy_shadow: true,
        legacy_relief: LegacyTextRelief::Embossed,
        ..Default::default()
      },
    );
    assert!(!caps.bold);
    assert_eq!(caps.complex_bold, Some(false));
    assert!(!caps.italic);
    assert_eq!(caps.complex_italic, Some(false));
    assert!(!caps.strikethrough);
    assert!(!caps.uppercase);
    assert!(!caps.hidden);
    assert!(!caps.legacy_outline);
    assert!(!caps.legacy_shadow);
    assert_eq!(caps.legacy_relief, LegacyTextRelief::None);

    let small_caps = catalog.character_run_style(
      Some("SmallCapsImprint"),
      TextStyle {
        small_caps: true,
        legacy_relief: LegacyTextRelief::Engraved,
        ..Default::default()
      },
    );
    assert!(!small_caps.small_caps);
    assert_eq!(small_caps.legacy_relief, LegacyTextRelief::None);
  }

